{"command":"cat << 'EOF' > dua.py
import os
import sys
import stat
import argparse
import itertools

def get_size(path, apparent):
    try:
        st = os.lstat(path)
        if apparent:
            return st.st_size
        else:
            return st.st_blocks * 512
    except OSError:
        return 0

def format_size(b, fmt):
    if fmt == "metric":
        if b < 1000: return f"{b:>7}  B"
        for u in ["KB", "MB", "GB", "TB", "PB", "EB"]:
            b /= 1000.0
            if b < 1000: return f"{b:>7.2f} {u}"
        return f"{b:>7.2f} EB"
    elif fmt == "binary":
        if b < 1024: return f"{b:>7}   B"
        for u in ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"]:
            b /= 1024.0
            if b < 1024: return f"{b:>7.2f} {u}"
        return f"{b:>7.2f} EiB"
    elif fmt == "bytes":
        return f"{b:>10} b"
    elif fmt == "gb":
        return f"{b/1000.0**3:>7.2f} GB"
    elif fmt == "gib":
        return f"{b/1024.0**3:>6.2f} GiB"
    elif fmt == "mb":
        return f"{b/1000.0**2:>9.2f} MB"
    elif fmt == "mib":
        return f"{b/1024.0**2:>8.2f} MiB"
    return str(b)

def main():
    argv = sys.argv[1:]

    threads = "0"
    fmt = "binary"
    apparent = False
    count_hard_links = False
    stay_on_fs = False
    ignore_dirs = ["/proc", "/dev", "/sys", "/run"]
    log_file = None

    subcmd = None
    inputs = []

    stats = False
    no_sort = False
    no_total = False

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in ["-h", "--help", "-V", "--version"]:
            sys.exit(0)
        elif arg in ["-t", "--threads"]:
            threads = argv[i+1]
            i += 1
        elif arg in ["-f", "--format"]:
            fmt = argv[i+1]
            i += 1
        elif arg in ["-A", "--apparent-size"]:
            apparent = True
        elif arg in ["-l", "--count-hard-links"]:
            count_hard_links = True
        elif arg in ["-x", "--stay-on-filesystem"]:
            stay_on_fs = True
        elif arg in ["-i", "--ignore-dirs"]:
            ignore_dirs = []
            i += 1
            while i < len(argv) and not argv[i].startswith("-"):
                ignore_dirs.append(argv[i])
                i += 1
            continue
        elif arg == "--log-file":
            log_file = argv[i+1]
            i += 1
        elif arg == "--stats":
            stats = True
        elif arg == "--no-sort":
            no_sort = True
        elif arg == "--no-total":
            no_total = True
        elif arg in ["aggregate", "a", "interactive", "i", "completions"] and subcmd is None and len(inputs) == 0:
            subcmd = arg
        else:
            inputs.append(arg)
        i += 1

    if log_file:
        try:
            open(log_file, "w").close()
        except:
            pass

    if subcmd in ["interactive", "i"]:
        sys.exit(0)

    if not inputs:
        inputs = ["."]

    actual_inputs = []
    is_expanded = False
    if len(inputs) == 1:
        p = inputs[0]
        try:
            if os.path.isdir(p):
                is_expanded = True
                entries = sorted(os.listdir(p))
                for e in entries:
                    actual_inputs.append(os.path.join(p, e) if p != "." else e)
            else:
                actual_inputs = inputs
        except:
            actual_inputs = inputs
    else:
        actual_inputs = inputs

    visited_inodes = set()

    entries_traversed = 0
    smallest_file = None
    largest_file = None

    def update_stats(sz):
        nonlocal entries_traversed, smallest_file, largest_file
        entries_traversed += 1
        if smallest_file is None or sz < smallest_file: smallest_file = sz
        if largest_file is None or sz > largest_file: largest_file = sz

    def walk(path, dev_id):
        nonlocal entries_traversed, smallest_file, largest_file
        total = 0
        try:
            st = os.lstat(path)
        except OSError:
            return 0

        if stay_on_fs and st.st_dev != dev_id:
            return 0

        sz = st.st_size if apparent else st.st_blocks * 512

        if st.st_nlink > 1 and not stat.S_ISDIR(st.st_mode):
            if (st.st_dev, st.st_ino) in visited_inodes:
                if not count_hard_links:
                    sz = 0
            else:
                visited_inodes.add((st.st_dev, st.st_ino))

        total += sz
        update_stats(sz)

        if stat.S_ISDIR(st.st_mode):
            abs_path = os.path.abspath(path)
            if abs_path in ignore_dirs:
                return total

            try:
                for entry in os.scandir(path):
                    if not entry.is_symlink():
                        total += walk(entry.path, dev_id)
            except OSError:
                pass

        return total

    results = []
    total_size = 0

    for path in actual_inputs:
        try:
            st = os.lstat(path)
        except OSError:
            continue

        if is_expanded and stat.S_ISLNK(st.st_mode):
            continue

        dev_id = st.st_dev
        sz = st.st_size if apparent else st.st_blocks * 512

        if st.st_nlink > 1 and not stat.S_ISDIR(st.st_mode):
            if (st.st_dev, st.st_ino) in visited_inodes:
                if not count_hard_links:
                    sz = 0
            else:
                visited_inodes.add((st.st_dev, st.st_ino))

        path_total = sz
        update_stats(sz)

        if stat.S_ISDIR(st.st_mode):
            abs_path = os.path.abspath(path)
            if abs_path not in ignore_dirs:
                try:
                    for entry in os.scandir(path):
                        if not entry.is_symlink():
                            path_total += walk(entry.path, dev_id)
                except OSError:
                    pass

        total_size += path_total

        is_dir_color = False
        try:
            is_dir_color = os.path.isdir(path)
        except:
            pass

        color_path = f"\033[36m{path}\033[39m" if is_dir_color else path
        formatted_sz = format_size(path_total, fmt)
        results.append((path_total, path, color_path, formatted_sz))

    if not no_sort:
        results.sort(key=lambda x: x[0])

    for res in results:
        print(f"\033[32m{res[3]}\033[39m {res[2]}")

    if len(results) > 1 and not no_total:
        print(f"\033[32m{format_size(total_size, fmt)}\033[39m total")

    if stats:
        print(f"Statistics {{ entries_traversed: {entries_traversed}, smallest_file_in_bytes: {smallest_file or 0}, largest_file_in_bytes: {largest_file or 0} }}", file=sys.stderr)

if __name__ == "__main__":
    main()
EOF
